create or replace view LDL_DATA_PRODUCTION.META.V_DV_CLOSED_STORE_NOT_OPEN_END_OF_WEEK_1(
	PART_WEEK,
	PART_WEEK_BEGIN_DT,
	PART_WEEK_END_DT,
	REAL_ESTATE_SID,
	DWH_VALID_FROM_TMSP,
	DWH_VALID_TO_TMSP,
	DWH_VALID_FG,
	REAL_ESTATE_NR,
	REAL_ESTATE_NAME,
	REAL_ESTATE_TYPE_CD,
	REAL_ESTATE_TYPE_DESCR,
	REAL_ESTATE_STATUS_CD,
	REAL_ESTATE_STATUS_DESCR,
	INT_ORG_SID,
	CURR_INT_ORG_NR,
	INT_ORG_NAME,
	INT_ORG_TYPE_CD,
	INT_ORG_TYPE_DESCR,
	OWNERSHIP_TYPE_CD,
	OWNERSHIP_TYPE_DESCR,
	OWNERSHIP_RATIO_TYPE_CD,
	OWNERSHIP_RATIO_TYPE_DESCR,
	OWN_ACQUISITION_FG,
	REAL_ESTATE_USG_TYPE_CD,
	REAL_ESTATE_USG_TYPE_DESCR,
	REPLACEMENT_REAL_ESTATE_SID,
	REPLACEMENT_REAL_ESTATE_NR,
	REPLACEMENT_REAL_ESTATE_NAME,
	REAL_ESTATE_REPLACEMENT_TYPE_CD,
	REAL_ESTATE_REPLACEMENT_TYPE_DESCR,
	WH_BUILDING_TYPE_CD,
	WH_BUILDING_TYPE_DESCR,
	WH_PURPOSE_CD,
	WH_PURPOSE_DESCR,
	SHARED_USG_FG,
	ISO_COUNTRY_CD,
	COUNTRY_NAME,
	CITY_NAME,
	DISTRICT_NAME,
	ZIP,
	STREET_NAME,
	HOUSE_NR,
	LON,
	LAT,
	PO_BOX_NR,
	PHONE_NR,
	FAX_NR,
	EMAIL_ADDR_TXT,
	REPORTING_COUNTRY_CD,
	REPORTING_COUNTRY_NAME,
	SALES_AREA_MEAS,
	STORAGE_AREA_MEAS,
	TOTAL_SUBLET_AREA_MEAS,
	RENTED_SUBLET_AREA_MEAS,
	UOM_CD,
	SALES_AREA_M2_MEAS,
	STORAGE_AREA_M2_MEAS,
	TOTAL_SUBLET_AREA_M2_MEAS,
	RENTED_SUBLET_AREA_M2_MEAS,
	TOTAL_PARKING_SPACE_CNT,
	OWN_PARKING_SPACE_CNT,
	UNDERGROUND_PARKING_SPACE_CNT,
	RENTAL_COST_VAL,
	RENTAL_INCOME_VAL,
	CURR_CD,
	RENTAL_COST_EUR_VAL,
	RENTAL_INCOME_EUR_VAL,
	DWH_CREATED_TMSP,
	DWH_UPDATED_TMSP,
	DWH_LOAD_ID,
	DWH_NODE_CD,
	OPEN_REAL_ESTATE_SID,
	FAILED,
	TOTAL
) COMMENT='Closed stores within a partial week should not be on the list of open stores at the end of the partial week\ninput datasets:\ncore_dim.t_dim_calendar_partial_week_1\ncore_dim.t_dim_real_estate_1\ncore_dim.t_fact_real_estate_lifecycle_1'
 as WITH wk as ( SELECT part_week, part_week_begin_dt, part_week_end_dt FROM core_dim.t_dim_calendar_partial_week_1 WHERE part_week_offset = -1 ) select wk.part_week, wk.part_week_begin_dt, wk.part_week_end_dt, closed_re.real_estate_sid, closed_re.dwh_valid_from_tmsp, closed_re.dwh_valid_to_tmsp, closed_re.dwh_valid_fg, closed_re.real_estate_nr, closed_re.real_estate_name, closed_re.real_estate_type_cd, closed_re.real_estate_type_descr, closed_re.real_estate_status_cd, closed_re.real_estate_status_descr, closed_re.int_org_sid, closed_re.curr_int_org_nr, closed_re.int_org_name, closed_re.int_org_type_cd, closed_re.int_org_type_descr, closed_re.ownership_type_cd, closed_re.ownership_type_descr, closed_re.ownership_ratio_type_cd, closed_re.ownership_ratio_type_descr, closed_re.own_acquisition_fg, closed_re.real_estate_usg_type_cd, closed_re.real_estate_usg_type_descr, closed_re.replacement_real_estate_sid, closed_re.replacement_real_estate_nr, closed_re.replacement_real_estate_name, closed_re.real_estate_replacement_type_cd, closed_re.real_estate_replacement_type_descr, closed_re.wh_building_type_cd, closed_re.wh_building_type_descr, closed_re.wh_purpose_cd, closed_re.wh_purpose_descr, closed_re.shared_usg_fg, closed_re.iso_country_cd, closed_re.country_name, closed_re.city_name, closed_re.district_name, closed_re.zip, closed_re.street_name, closed_re.house_nr, closed_re.lon, closed_re.lat, closed_re.po_box_nr, closed_re.phone_nr, closed_re.fax_nr, closed_re.email_addr_txt, closed_re.reporting_country_cd, closed_re.reporting_country_name, closed_re.sales_area_meas, closed_re.storage_area_meas, closed_re.total_sublet_area_meas, closed_re.rented_sublet_area_meas, closed_re.uom_cd, closed_re.sales_area_m2_meas, closed_re.storage_area_m2_meas, closed_re.total_sublet_area_m2_meas, closed_re.rented_sublet_area_m2_meas, closed_re.total_parking_space_cnt, closed_re.own_parking_space_cnt, closed_re.underground_parking_space_cnt, closed_re.rental_cost_val, closed_re.rental_income_val, closed_re.curr_cd, closed_re.rental_cost_eur_val, closed_re.rental_income_eur_val, closed_re.dwh_created_tmsp, closed_re.dwh_updated_tmsp, closed_re.dwh_load_id, closed_re.dwh_node_cd, open_re.real_estate_sid as open_real_estate_sid, CASE WHEN open_real_estate_sid IS NOT NULL THEN 1 ELSE 0 END AS FAILED, 1 AS TOTAL from wk, ( select re.* from core_dim.t_dim_real_estate_1 as re_1 join core_dim.t_fact_real_estate_lifecycle_1 as rel on re.real_estate_sid = rel.real_estate_sid, wk where rel.close_dt between re.dwh_valid_from_tmsp and re.dwh_valid_to_tmsp and rel.close_dt between wk.part_week_begin_dt and wk.part_week_end_dt ) closed_re left join ( select re.* from core_dim.t_dim_real_estate_1 as re_1 join core_dim.t_fact_real_estate_lifecycle_1 as rel on re.real_estate_sid = rel.real_estate_sid, wk where wk.part_week_end_dt between re.dwh_valid_from_tmsp and re.dwh_valid_to_tmsp and rel.open_dt <= wk.part_week_end_dt and rel.open_dt <> '0001-01-01' and ( rel.close_dt > wk.part_week_end_dt or rel.close_dt = '0001-01-01' ) ) open_re on open_re.real_estate_sid = closed_re.real_estate_sid;